const extraStyle=document.createElement("link");extraStyle.rel="stylesheet";extraStyle.href="./architecture.css";document.head.appendChild(extraStyle);
const circuits=window.TVS_CIRCUITS,industries=window.TVS_INDUSTRIES;let activeFilter="All",previousView="map";
const rows=["Power","Communication","High Speed","Industrial IO","Inductive Load","MOSFET","Energy Storage","Security","Data Center"];
function showView(name){document.querySelectorAll(".view").forEach(v=>v.classList.remove("active"));document.querySelector(`#${name}-view`).classList.add("active");document.querySelectorAll("#main-nav button").forEach(b=>b.classList.toggle("active",b.dataset.view===name));if(name!=="detail")previousView=name;window.scrollTo({top:0,behavior:"smooth"})}
document.querySelectorAll("#main-nav button").forEach(b=>b.onclick=()=>showView(b.dataset.view));document.querySelector("#back").onclick=()=>showView(previousView);
function renderMatrix(){const heads=Object.keys(industries);document.querySelector("#matrix").innerHTML=`<table class="matrix-table"><thead><tr><th>Interface family</th>${heads.map(h=>`<th>${h}</th>`).join("")}</tr></thead><tbody>${rows.map(row=>`<tr><th>${row}</th>${heads.map(ind=>{const hit=circuits.find(c=>c.group===row&&c.industries.includes(ind));return `<td>${hit?`<button title="${hit.title}" data-id="${hit.id}" class="${hit.status==='golden'?'golden':''}"></button>`:"—"}</td>`}).join("")}</tr>`).join("")}</tbody></table>`;document.querySelectorAll("#matrix button").forEach(b=>b.onclick=()=>openCircuit(b.dataset.id))}
function renderGolden(){document.querySelector("#golden-list").innerHTML=circuits.filter(c=>c.status==="golden").map(c=>`<button class="golden-item" data-id="${c.id}"><b>${c.title}</b><span>${c.group} · ${c.voltage}</span></button>`).join("");document.querySelectorAll(".golden-item").forEach(b=>b.onclick=()=>openCircuit(b.dataset.id))}
function renderCatalog(query=""){const q=query.toLowerCase();const list=circuits.filter(c=>(activeFilter==="All"||c.group===activeFilter)&&`${c.title} ${c.group} ${c.voltage} ${c.industries}`.toLowerCase().includes(q));document.querySelector("#catalog").innerHTML=list.map(c=>`<article class="catalog-card ${c.status==='golden'?'gold':''}" data-id="${c.id}"><span class="status-tag">${c.status==='golden'?'GOLDEN':'PLANNED'}</span><small>${c.group} · ${c.voltage}</small><h3>${c.title}</h3><p>${c.industries.join(" · ")}</p></article>`).join("");document.querySelectorAll(".catalog-card").forEach(card=>card.onclick=()=>openCircuit(card.dataset.id))}
function renderFilters(){const groups=["All",...new Set(circuits.map(c=>c.group))];document.querySelector("#filters").innerHTML=groups.map(g=>`<button class="${g===activeFilter?'active':''}" data-group="${g}">${g}</button>`).join("");document.querySelectorAll("#filters button").forEach(b=>b.onclick=()=>{activeFilter=b.dataset.group;renderFilters();renderCatalog(document.querySelector("#search").value)})}
document.querySelector("#search").oninput=e=>renderCatalog(e.target.value);
function renderIndustries(){document.querySelector("#industry-grid").innerHTML=Object.entries(industries).map(([name,items])=>`<article><small>${name.toUpperCase()}</small><h3>${name}</h3><ul>${items.map(i=>`<li>${i}</li>`).join("")}</ul></article>`).join("")}
const goldenDetails={
"24v-input":{model:"Littelfuse SMBJ33A",protected:"TI LM5164 · 100V Abs Max",residual:"60V design ceiling",reason:"33V VRWM 覆盖 30V 持续高线；53.3V 最大钳位值低于 100V 后级耐压。SMBJ30A 的 VRWM 太贴近高线，SMBJ36A 的 VC 更高。"},
"rs485":{model:"Littelfuse SM712-02HTG",protected:"TI THVD2450 · ±70V Bus Fault",residual:"+34V / −22V budget",reason:"−7V/+12V 非对称工作窗口与 RS485 匹配，并明确给出 19A、8/20µs 能力。普通 ESD 阵列通常不能替代浪涌 TVS。"},
"can":{model:"Littelfuse SM24CANB",protected:"TI TCAN1042-Q1 · bus interface",residual:"Engineering assumption – validate",reason:"面向 CAN/CAN-FD 的双线匹配阵列。最终 VC 必须与选定收发器故障电压、ISO 7637/10605 脉冲和线束阻抗联合验证。"},
"bms-contactor":{model:"Littelfuse SMBJ33A",protected:"100V N-MOSFET contactor driver",residual:"≈85V VDS budget*",reason:"24V 线圈关断时，33V TVS 在释放速度与 MOSFET VDS 之间折中。不能用普通续流二极管替代，否则接触器释放时间显著延长。"},
"54v-dc":{model:"Littelfuse SMCJ58A + Active Clamp",protected:"48/54V Hot-swap FET stage",residual:"TVS-only margin insufficient",reason:"54V 母线容差使低 VRWM 器件不可用，而高 VRWM TVS 的 VC 又接近 100V 电子器件极限，因此采用 TVS + active surge stopper / 150V FET 分级方案。"}}
function waveSvg(){return `<svg viewBox="0 0 520 180"><line class="axis" x1="40" y1="150" x2="500" y2="150"/><line class="axis" x1="40" y1="20" x2="40" y2="150"/><path class="wave" d="M40 150C58 146 65 38 102 34C160 40 215 95 280 123C350 145 425 149 500 150"/><path class="clamp" d="M40 150C60 145 70 90 105 88C190 90 310 137 500 150"/><text class="wave-value" x="108" y="27">SURGE</text><text class="wave-label" x="110" y="83">clamped waveform</text></svg>`}
function openCircuit(id){const c=circuits.find(x=>x.id===id),d=goldenDetails[id];document.querySelector("#detail").innerHTML=d?`<div class="title-row"><div><span>${c.group.toUpperCase()} · ${c.voltage}</span><h2>${c.title}</h2><p>${c.industries.join(" · ")}</p></div><div class="verdict">${d.residual}</div></div><section class="top-grid"><article class="wave-card"><div class="card-title"><div><small>INPUT TRANSIENT</small><h3>浪涌输入与钳位波形</h3></div><span>Waveform-dependent</span></div><div id="waveform">${waveSvg()}</div></article><article class="residual-card"><div class="card-title"><div><small>DEVICE COORDINATION</small><h3>${d.model}</h3></div></div><div class="voltage-stack"><div><span>TVS / Clamp</span><strong>${d.model.split(" ").pop()}</strong></div><b>→</b><div class="result"><span>后级耐压</span><strong>${d.protected}</strong></div></div><p>${d.reason}</p></article></section><section class="circuit-card"><div class="card-title"><div><small>REFERENCE TOPOLOGY</small><h3>Connector → TVS → Filter / Driver → Protected Stage</h3></div></div><div id="circuit"><svg viewBox="0 0 1000 360"><path class="protectbox" d="M610 90H960V270H610Z"/><path class="wire" d="M60 180H210M310 180H430M530 180H700M800 180H920M360 180V290M360 330V350"/><path class="surge" d="M35 130H90V180H360V345"/><text class="surge-label" x="35" y="115">SURGE CURRENT</text>${block(260,180,"F1 / R","Series protection")}${block(480,180,"L / CMC","Filter")}${block(750,180,"U / Q","${d.protected}")}${block(920,180,"LOAD","Protected rail / logic")}${tvsBlock(360,310,"TVS",d.model)}</svg></div><div class="parts"><span><b>TVS</b> · ${d.model}</span><span><b>Protected</b> · ${d.protected}</span><span><b>Residual</b> · ${d.residual}</span></div></section><section class="decision-grid"><article class="why"><small>WHY THIS TVS</small><h3>选型理由</h3><ul><li>${d.reason}</li><li>实际 IC 端峰值必须加入 L·di/dt 布局过冲。</li><li>器件型号为 Reference Example Only，必须进行系统浪涌测试。</li></ul></article><article class="reject"><small>ENGINEERING CHECK</small><h3>必须验证</h3><div class="alt"><b>VRWM</b><p>覆盖最大持续工作电压及容差，不发生误导通。</p></div><div class="alt"><b>VC / Abs Max</b><p>TVS VC 加寄生过冲必须低于后级绝对最大额定值。</p></div><div class="alt"><b>IPP / Energy</b><p>依据波形、源阻抗、温度和重复次数校核。</p></div></article></section>`:`<div class="detail-placeholder"><small>${c.group}</small><h2>${c.title}</h2><p>该线路已进入 Phase 2 内容队列。数据结构、行业映射和页面入口已经建立；具体型号与残压数据将在官方资料验证后发布。</p></div>`;showView("detail")}
function block(x,y,r,v){if(v==="${d.protected}")v="Protected Stage";return `<g><rect class="partbox" x="${x-55}" y="${y-34}" width="110" height="68" rx="6"/><text class="ref" x="${x}" y="${y-4}">${r}</text><text class="value" x="${x}" y="${y+16}">${v}</text></g>`}function tvsBlock(x,y,r,v){return `<g><rect class="tvsbox" x="${x-70}" y="${y-27}" width="140" height="54" rx="6"/><text class="ref" x="${x}" y="${y-3}">${r}</text><text class="value" x="${x}" y="${y+15}">${v}</text></g>`}
renderMatrix();renderGolden();renderFilters();renderCatalog();renderIndustries();
